#!/usr/bin/env node
// Rewrites videos/index.ts to import every videos/*.json.
import { readdirSync, writeFileSync } from 'node:fs';
const ids = readdirSync('videos').filter((f) => f.endsWith('.json')).map((f) => f.slice(0, -5)).sort();
const camel = (s) => s.replace(/-([a-z0-9])/g, (_, c) => c.toUpperCase());
writeFileSync(
	'videos/index.ts',
	'// Every video script. Generated by tools/index-videos.mjs: run `npm run index-videos` after adding a JSON file.\n' +
		ids.map((i) => `import ${camel(i)} from './${i}.json';\n`).join('') +
		`\nexport const videos: unknown[] = [${ids.map(camel).join(', ')}];\n`
);
console.log(`videos/index.ts: ${ids.length} scripts`);
